import{_ as a,C as r,o,c as i,E as s,a2 as c}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"OAuth 刷新成功后，持久化失败不是普通失败","description":"","frontmatter":{"title":"OAuth 刷新成功后，持久化失败不是普通失败","date":"2026-08-19","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"What state should an OAuth client expose when the authorization server has issued refreshed credentials but local durable persistence fails afterward?","summary":"远端刷新成功与本地保存失败可以同时成立。MCP TypeScript SDK 当日合并变更把两者从同一异常分支中拆开，使持久化错误保持可见；这改善了恢复所需的状态证据，但并不提供回滚或分布式原子性。","sources":["research/analysis/Q-20260819-03-oauth-refresh-split-commit.md"],"item_id":"Q-20260819-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-oauth-refresh-split-commit-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-08-19-oauth-refresh-split-commit.md","filePath":"zh/engineering/2026-08-19-oauth-refresh-split-commit.md","lastUpdated":1787382334000}'),n={name:"zh/engineering/2026-08-19-oauth-refresh-split-commit.md"};function p(l,e,h,d,u,m){const t=r("ArticleCover");return o(),i("div",null,[s(t,{image:"/assets/covers/daily-2026-08-19-oauth-refresh-split-commit-cover-v2.png",kicker:"开源工程 · 每日研究",title:"OAuth 刷新成功后，持久化失败不是普通失败",summary:"远端刷新成功与本地保存失败可以同时成立。MCP TypeScript SDK 当日合并变更把两者从同一异常分支中拆开，使持久化错误保持可见；这改善了恢复所需的状态证据，但并不提供回滚或分布式原子性。",version:"Q-20260819-03",status:"Daily Runtime V5 · 2026-08-19",languageHref:"/en/engineering/2026-08-19-oauth-refresh-split-commit",languageLabel:"English"}),e[0]||(e[0]=c('<h1 id="oauth-刷新成功后-持久化失败不是普通失败" tabindex="-1">OAuth 刷新成功后，持久化失败不是普通失败 <a class="header-anchor" href="#oauth-刷新成功后-持久化失败不是普通失败" aria-label="Permalink to &quot;OAuth 刷新成功后，持久化失败不是普通失败&quot;">​</a></h1><p>授权服务器已经返回新的访问令牌和刷新令牌，客户端却在保存时遇到“磁盘已满”。这时认证流程到底成功了，还是失败了？</p><p>如果只允许一个布尔答案，系统很容易丢失最重要的事实：远端权威状态可能已经推进，本地持久状态却没有同步推进。把这种情况归类为普通刷新失败，随后自动跳转到重新授权，不仅描述错误，还可能掩盖在令牌轮换策略下难以恢复的凭据断点。</p><p>2026-08-19 合并的一项 MCP TypeScript SDK 变更修正了这个故障边界。变更前，<code>refreshAuthorization</code> 与 <code>provider.saveTokens</code> 处于同一个 <code>catch</code> 路径，部分异常会继续进入新的授权请求。变更后，只有远端刷新调用留在受保护的刷新块中；远端成功后再调用 <code>saveTokens</code>，其拒绝会直接向调用方传播。回归测试先取得新令牌，再让保存操作以“磁盘已满”失败，要求认证流程传播同一个持久化错误，并确认没有调用重定向授权。</p><p>这组证据支持一个有界的可靠性判断：<strong>当远端签发与本地持久化是两个操作时，OAuth 刷新就是分段提交工作流。远端成功后的本地失败属于部分成功，必须保持可见。</strong></p><h2 id="两个操作成功在不同的权威面" tabindex="-1">两个操作成功在不同的权威面 <a class="header-anchor" href="#两个操作成功在不同的权威面" aria-label="Permalink to &quot;两个操作成功在不同的权威面&quot;">​</a></h2><p>远端刷新交换改变的是授权服务器所认可的凭据状态。本地保存改变的是客户端在进程重启、崩溃或下一次请求后还能否恢复这些凭据。</p><p>两者按顺序发生，却不共享原子提交。远端调用返回成功时，服务器一侧已经完成了它承诺的操作；本地存储随后失败，不能把刚才的远端成功“变回未发生”。如果服务器采用刷新令牌轮换，旧令牌甚至可能不再可用。</p><p>因此，这个状态不是简单的“认证失败”，而是两个提交点不一致：远端已提交，本地未持久提交。可靠恢复必须从这个状态事实开始。</p><h2 id="catch-边界本身就是可靠性模型" tabindex="-1"><code>catch</code> 边界本身就是可靠性模型 <a class="header-anchor" href="#catch-边界本身就是可靠性模型" aria-label="Permalink to &quot;`catch` 边界本身就是可靠性模型&quot;">​</a></h2><p>异常处理常被视为代码清理，但这里的 <code>catch</code> 范围决定了系统能否区分哪一侧已经成功。</p><p>把远端交换和本地保存放在同一异常分支时，<code>saveTokens</code> 的失败可能被刷新错误处理逻辑接管。系统随后看到的只是“刷新阶段出了问题”，而不是“已取得新凭据但未能持久化”。如果再自动进入重新授权，原始部分状态就被新的流程覆盖。</p><p>同日变更通过移动一行故障边界保留了语义：刷新请求的失败继续走刷新恢复逻辑，保存失败则以保存失败的身份传播。回归测试证明，在已测试路径中，持久化错误不会再静默变成重定向。</p><p>这并非只是更准确的错误文字。它保留了恢复决策所需的证据分类。</p><h2 id="保持可见是恢复前提-不是恢复本身" tabindex="-1">保持可见是恢复前提，不是恢复本身 <a class="header-anchor" href="#保持可见是恢复前提-不是恢复本身" aria-label="Permalink to &quot;保持可见是恢复前提，不是恢复本身&quot;">​</a></h2><p>传播持久化错误能让调用方知道远端交换已经成功、本地耐久性没有建立。调用方于是可以根据部署策略选择有界重试、切换安全存储、停止服务并告警操作员，或进入显式协调流程。</p><p>但可见性本身没有解决部分状态。当前变更没有提供自动重试，也没有定义包含新凭据的标准恢复对象。若存储提供方可能发生部分写入，调用方仍需知道写入是原子替换、仅被接收，还是已经耐久落盘。</p><p>更强的接口可以让令牌提供方声明：</p><ul><li>是否支持原子替换；</li><li>成功返回是否代表耐久确认；</li><li>失败后重试是否安全；</li><li>是否可能出现部分写入；</li><li>恢复流程需要哪些非敏感状态证据。</li></ul><p>这些能力不能从一个通用 <code>saveTokens</code> 方法名中自动推断。</p><h2 id="错误传播不等于事务性" tabindex="-1">错误传播不等于事务性 <a class="header-anchor" href="#错误传播不等于事务性" aria-label="Permalink to &quot;错误传播不等于事务性&quot;">​</a></h2><p>现有证据来自一个已合并 SDK 变更及其仓库测试，不是独立 OAuth 可靠性基准。服务器侧后果还取决于具体授权服务器策略；刷新令牌轮换并非所有实现都采用。</p><p>该变更没有跨授权服务器与本地存储建立分布式事务，不能回滚服务器侧签发，也没有保证“仅一次”保存。即使本地提供方能做到原子替换，远端与本地两个系统之间仍不存在共同提交。</p><p>因此，准确结论是：故障被正确分类并保持可见，安全恢复因此有了必要证据；但回滚、重试、协调和操作处置仍需要独立设计。</p><p>接下来的问题应成为接口合同，而不是运维猜测：SDK 是否应暴露结构化的部分成功错误，记录远端签发已完成而本地耐久性失败？令牌提供方如何机器可读地声明原子性、耐久确认和安全重试能力？无界面部署如何及时告警操作员，避免下一次启动才发现持久凭据没有更新？只有把“哪一侧已经提交”作为一等事实，恢复逻辑才不会从错误的失败模型出发。</p><p><strong>一手证据：</strong> <a href="https://github.com/modelcontextprotocol/typescript-sdk/commit/3924de99df834302d89f5997a1b64ca268282284" target="_blank" rel="noreferrer">MCP TypeScript SDK 合并提交 3924de99</a>。代码与仓库测试属于公开一手证据，不构成分布式事务性、回滚或通用令牌轮换行为的独立验证。</p>',26))])}const g=a(n,[["render",p]]);export{f as __pageData,g as default};
